from __future__ import annotations

import hashlib
import re
from typing import Any


CRITICAL_TERMS = {
    "payer", "paiement", "transaction", "virement", "autoriser",
    "execute", "exécuter", "act", "merge", "modifier", "kernel",
    "deploy", "production", "delete", "supprimer"
}

KERNEL_MUTATION_TERMS = {
    "kernel", "merge", "canon", "proof", "lean", "tla", "production"
}


def _text(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _sha256(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _norm_float(value: Any, default: float = 0.0) -> float:
    try:
        x = float(value)
    except Exception:
        x = default
    if x < 0.0:
        return 0.0
    if x > 1.0:
        return 1.0
    return round(x, 6)


def _tree_vector(value: Any) -> list[float]:
    if isinstance(value, list):
        out = [_norm_float(v) for v in value[:34]]
    elif isinstance(value, dict):
        out = [0.0] * 34
        for k, v in value.items():
            s = str(k).upper().replace("TREE_", "")
            try:
                idx = int(s) - 1
                if 0 <= idx < 34:
                    out[idx] = _norm_float(v)
            except Exception:
                pass
    else:
        out = []

    while len(out) < 34:
        out.append(0.0)

    return out[:34]


def _active_tree_ids(vector: list[float], threshold: float = 0.15) -> list[str]:
    return [
        f"TREE_{i + 1:02d}"
        for i, score in enumerate(vector)
        if score > threshold
    ]


def _tokens(text: str) -> list[str]:
    return re.findall(r"[A-Za-zÀ-ÿ0-9_]+", text.lower())


def _requires_x108(intent: str, risk: float, policy_scope: str) -> bool:
    words = set(_tokens(intent))
    if risk >= 0.75:
        return True
    if words & CRITICAL_TERMS:
        return True
    if policy_scope.upper() != "READONLY_CONTEXT":
        return True
    return False


